#include <string>
#include <unordered_set>

using namespace std;

class Solution {
public:
    bool halvesAreAlike(string s) {
        unordered_set<char> vowels = {'a','e','i','o','u','A','E','I','O','U'};
        int mid = s.size() / 2, count = 0;
        for (int i = 0; i < s.size(); ++i) {
            if (vowels.count(s[i])) count += (i < mid ? 1 : -1);
        }
        return count == 0;
    }
};
